void add_edge(int u, int v) {
    to[edge_cnt] = v;
    nxt[edge_cnt] = head[u];
    head[u] = edge_cnt++;
}

int bfs(int start, int dist[]) {
    int front = 0, back = 0;
    memset(dist, -1, sizeof(int) * (n+1));
    dist[start] = 0;
    queue[back++] = start;
    int farthest = start;
    while (front < back) {
        int u = queue[front++];
        if (dist[u] > dist[farthest]) farthest = u;
        for (int e = head[u]; e != -1; e = nxt[e]) {
            int v = to[e];
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                queue[back++] = v;
            }
        }
    }
    return farthest;
}

