#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int to, next;
} Edge;

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    if (N == 1) {
        printf("0\n");
        return 0;
    }

    int M = 2 * (N - 1);
    Edge *edges = (Edge *)malloc(sizeof(Edge) * M);
    int *head = (int *)malloc(sizeof(int) * (N + 1));
    int *deg = (int *)calloc(N + 1, sizeof(int));

    for (int i = 1; i <= N; i++) head[i] = -1;

    int ecnt = 0;
    for (int i = 0; i < N - 1; i++) {
        int u, v;
        scanf("%d %d", &u, &v);

        edges[ecnt].to = v;
        edges[ecnt].next = head[u];
        head[u] = ecnt++;
        deg[u]++;

        edges[ecnt].to = u;
        edges[ecnt].next = head[v];
        head[v] = ecnt++;
        deg[v]++;
    }

    /* Find one endpoint of tree diameter by BFS from 1 */
    int *queue = (int *)malloc(sizeof(int) * (N + 5));
    int *distA = (int *)malloc(sizeof(int) * (N + 1));
    int *distB = (int *)malloc(sizeof(int) * (N + 1));

    for (int i = 1; i <= N; i++) distA[i] = -1;
    int front = 0, back = 0;
    queue[back++] = 1;
    distA[1] = 0;

    while (front < back) {
        int u = queue[front++];
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            if (distA[v] == -1) {
                distA[v] = distA[u] + 1;
                queue[back++] = v;
            }
        }
    }

    int A = 1;
    for (int i = 1; i <= N; i++) {
        if (distA[i] > distA[A]) A = i;
    }

    /* BFS from A */
    for (int i = 1; i <= N; i++) distA[i] = -1;
    front = back = 0;
    queue[back++] = A;
    distA[A] = 0;

    while (front < back) {
        int u = queue[front++];
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            if (distA[v] == -1) {
                distA[v] = distA[u] + 1;
                queue[back++] = v;
            }
        }
    }

    int B = A;
    for (int i = 1; i <= N; i++) {
        if (distA[i] > distA[B]) B = i;
    }

    /* BFS from B */
    for (int i = 1; i <= N; i++) distB[i] = -1;
    front = back = 0;
    queue[back++] = B;
    distB[B] = 0;

    while (front < back) {
        int u = queue[front++];
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            if (distB[v] == -1) {
                distB[v] = distB[u] + 1;
                queue[back++] = v;
            }
        }
    }

    /*
      In a tree, minimum steps to visit all vertices starting from v
      = 2*(N-1) - eccentricity(v),
      where eccentricity(v) = max distance from v to any vertex.
      For a tree, eccentricity(v) = max(distA[v], distB[v]) where A,B are diameter endpoints.
    */
    long long total = 2LL * (N - 1);
    for (int i = 1; i <= N; i++) {
        long long ecc = distA[i] > distB[i] ? distA[i] : distB[i];
        printf("%lld\n", total - ecc);
    }

    free(edges);
    free(head);
    free(deg);
    free(queue);
    free(distA);
    free(distB);

    return 0;
}

