int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<vector<int>> g(n);
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        cin >> u >> v;
        u--, v--;
        g[u].push_back(v);
        g[v].push_back(u);
    }

    vector<int> down(n, 0), down2(n, 0), up(n, 0);
    vector<int> child1(n, -1), child2(n, -1);

    function<void(int, int)> dfs1 = [&](int u, int p) {
        for (int v : g[u]) {
            if (v == p) continue;
            dfs1(v, u);
            int dist = down[v] + 1;
            if (dist > down[u]) {
                down2[u] = down[u];
                down[u] = dist;
                child2[u] = child1[u];
                child1[u] = v;
            } else if (dist > down2[u]) {
                down2[u] = dist;
                child2[u] = v;
            }
        }
    };

    function<void(int, int)> dfs2 = [&](int u, int p) {
        for (int v : g[u]) {
            if (v == p) continue;
            if (v == child1[u]) {
                up[v] = max(up[u], down2[u]) + 1;
            } else {
                up[v] = max(up[u], down[u]) + 1;
            }
            dfs2(v, u);
        }
    };

    dfs1(0, -1);
    dfs2(0, -1);

    for (int i = 0; i < n; i++) {
        int maxDist = max(down[i], up[i]);
        cout << 2 * (n - 1) - maxDist << "\n";
    }

    return 0;
}

