        g[v].push_back(u);
    }

    auto bfs = [&](int src) {
        vector<int> dist(N + 1, -1);
        queue<int> q;
        q.push(src);
        dist[src] = 0;
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            for (int v : g[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.push(v);
                }
            }
        }
        int far = src;
        for (int i = 1; i <= N; ++i) {
            if (dist[i] > dist[far]) far = i;
        }
        return make_pair(far, dist);
    };

    // Find diameter endpoints s and t
    auto p1 = bfs(1);
    int s = p1.first;
    auto p2 = bfs(s);
    int t = p2.first;
    vector<int> ds = p2.second;
    vector<int> dt = bfs(t).second;

    // For a tree, minimum steps to visit all vertices starting at v:
    // 2*(N-1) - max(dist(v, s), dist(v, t))
    // where s,t are endpoints of a diameter.
    for (int v = 1; v <= N; ++v) {
        long long ans = 2LL * (N - 1) - max(ds[v], dt[v]);
        cout << ans << '\n';
    }

