        int[] dist1 = bfs(1);
        int far1 = 1;
        for (int i = 1; i <= n; i++) {
            if (dist1[i] > dist1[far1]) far1 = i;
        }

        // BFS from far1 to get distances from one end
        int[] distFromFar1 = bfs(far1);
        int far2 = far1;
        for (int i = 1; i <= n; i++) {
            if (distFromFar1[i] > distFromFar1[far2]) far2 = i;
        }

        // BFS from far2 to get distances from the other end
        int[] distFromFar2 = bfs(far2);

        int base = 2 * (n - 1);
        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= n; i++) {
            int maxDist = Math.max(distFromFar1[i], distFromFar2[i]);
            sb.append(base - maxDist).append("\n");
        }
        System.out.print(sb);
    }

