    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        N = Integer.parseInt(br.readLine().trim());

        adj = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) adj[i] = new ArrayList<>();

        for (int i = 0; i < N - 1; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken());
            int v = Integer.parseInt(st.nextToken());
            adj[u].add(v);
            adj[v].add(u);
        }

        // BFS from vertex 1 to find farthest vertex u
        int[] d1 = bfs(1);
        int u = 1;
        for (int i = 1; i <= N; i++) if (d1[i] > d1[u]) u = i;

        // BFS from u to find farthest vertex w
        int[] du = bfs(u);
        int w = 1;
        for (int i = 1; i <= N; i++) if (du[i] > du[w]) w = i;

        // BFS from w
        int[] dw = bfs(w);

        StringBuilder sb = new StringBuilder();
        for (int v = 1; v <= N; v++) {
            int maxDist = Math.max(du[v], dw[v]);
            sb.append(2 * (N - 1) - maxDist).append('\n');
        }
        System.out.print(sb);
    }

    static int[] bfs(int start) {
        int[] dist = new int[N + 1];
        Arrays.fill(dist, -1);
        Queue<Integer> queue = new ArrayDeque<>();
        dist[start] = 0;
        queue.add(start);
        while (!queue.isEmpty()) {
            int cur = queue.poll();
            for (int nb : adj[cur]) {
                if (dist[nb] == -1) {
                    dist[nb] = dist[cur] + 1;
                    queue.add(nb);
                }
            }
        }
        return dist;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static int N;
    static ArrayList<Integer>[] g;
    static int[] parent, order, depth;
    static int[] subSize;
    static long[] down, up, ans;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        N = fs.nextInt();

        g = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) g[i] = new ArrayList<>();

        for (int i = 0; i < N - 1; i++) {
            int u = fs.nextInt();
            int v = fs.nextInt();
            g[u].add(v);
            g[v].add(u);
        }

        parent = new int[N + 1];
        depth = new int[N + 1];
        order = new int[N];
        buildOrderIterative(1);

        subSize = new int[N + 1];
        down = new long[N + 1];
        up = new long[N + 1];
        ans = new long[N + 1];

        // Post-order DP for subtree
        for (int i = N - 1; i >= 0; i--) {
            int u = order[i];
            subSize[u] = 1;
            long best = 0;
            for (int v : g[u]) {
                if (v == parent[u]) continue;
                subSize[u] += subSize[v];
                best = Math.max(best, down[v] + 1);
            }
            down[u] = best;
        }

        // Pre-order DP for outside subtree
        for (int idx = 0; idx < N; idx++) {
            int u = order[idx];

            int m = g[u].size();
            long[] pref = new long[m];
            long[] suff = new long[m];

            for (int i = 0; i < m; i++) {
                int v = g[u].get(i);
                long val;
                if (v == parent[u]) {
                    val = up[u];
                } else {
                    val = down[v] + 1;
                }
                pref[i] = val;
                if (i > 0) pref[i] = Math.max(pref[i], pref[i - 1]);
            }

            for (int i = m - 1; i >= 0; i--) {
                int v = g[u].get(i);
                long val;
                if (v == parent[u]) {
                    val = up[u];
                } else {
                    val = down[v] + 1;
                }
                suff[i] = val;
                if (i + 1 < m) suff[i] = Math.max(suff[i], suff[i + 1]);
            }

            for (int i = 0; i < m; i++) {
                int v = g[u].get(i);
                if (v == parent[u]) continue;

                long bestExcludingV = 0;
                if (i > 0) bestExcludingV = Math.max(bestExcludingV, pref[i - 1]);
                if (i + 1 < m) bestExcludingV = Math.max(bestExcludingV, suff[i + 1]);

                up[v] = bestExcludingV + 1;
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int u = 1; u <= N; u++) {
            long farthest = Math.max(down[u], up[u]);
            long result = 2L * (N - 1) - farthest;
            sb.append(result).append('\n');
        }
        System.out.print(sb.toString());
    }

    static void buildOrderIterative(int root) {
        int[] stack = new int[N];
        int top = 0;
        stack[top++] = root;
        parent[root] = 0;
        depth[root] = 0;

        int idx = 0;
        while (top > 0) {
            int u = stack[--top];
            order[idx++] = u;
            for (int v : g[u]) {
                if (v == parent[u]) continue;
                parent[v] = u;
                depth[v] = depth[u] + 1;
                stack[top++] = v;
            }
        }
    }
}
